-- The schema after every migration in authz/services/context/migrations, generated by tools/db-schema.
-- Read it; don't edit it: change the schema with a new migration, then run tools/db-schema.

CREATE TABLE public.group_members (
    group_id uuid NOT NULL,
    member_id uuid NOT NULL
);

CREATE TABLE public.groups (
    scim_id uuid NOT NULL,
    display_name text NOT NULL,
    external_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.humans (
    scim_id uuid NOT NULL,
    user_name text NOT NULL,
    external_id text,
    display_name text,
    active boolean DEFAULT true NOT NULL,
    resource jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.resources (
    id text NOT NULL,
    source text NOT NULL,
    kind text NOT NULL,
    name text NOT NULL,
    parent text,
    owner text,
    sensitivity text,
    labels text[] DEFAULT '{}'::text[] NOT NULL,
    sharing jsonb DEFAULT '[]'::jsonb NOT NULL,
    text text,
    url text,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    classified_sensitivity text,
    classified_by text,
    classification_reason text,
    classified_at timestamp with time zone
);

CREATE TABLE public.service_accounts (
    id text NOT NULL,
    owner text NOT NULL,
    ai boolean NOT NULL,
    groups text[] DEFAULT '{}'::text[] NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    created_by text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public.snapshot_version (
    singleton boolean DEFAULT true NOT NULL,
    version bigint NOT NULL,
    CONSTRAINT snapshot_version_singleton_check CHECK (singleton)
);

CREATE TABLE public.work_items (
    id text NOT NULL,
    source text NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    state text DEFAULT 'open'::text NOT NULL,
    assignees text[] DEFAULT '{}'::text[] NOT NULL,
    resources text[] DEFAULT '{}'::text[] NOT NULL,
    attributes jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY public.group_members
    ADD CONSTRAINT group_members_pkey PRIMARY KEY (group_id, member_id);

ALTER TABLE ONLY public.groups
    ADD CONSTRAINT groups_pkey PRIMARY KEY (scim_id);

ALTER TABLE ONLY public.humans
    ADD CONSTRAINT humans_pkey PRIMARY KEY (scim_id);

ALTER TABLE ONLY public.resources
    ADD CONSTRAINT resources_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.service_accounts
    ADD CONSTRAINT service_accounts_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.snapshot_version
    ADD CONSTRAINT snapshot_version_pkey PRIMARY KEY (singleton);

ALTER TABLE ONLY public.work_items
    ADD CONSTRAINT work_items_pkey PRIMARY KEY (id);

CREATE INDEX group_members_member ON public.group_members USING btree (member_id);

CREATE UNIQUE INDEX groups_display_name ON public.groups USING btree (lower(display_name));

CREATE UNIQUE INDEX humans_user_name ON public.humans USING btree (lower(user_name));

CREATE INDEX resources_owner ON public.resources USING btree (owner);

CREATE INDEX resources_parent ON public.resources USING btree (parent);

CREATE INDEX resources_source_kind ON public.resources USING btree (source, kind);

CREATE INDEX resources_to_classify ON public.resources USING btree (updated_at) WHERE ((classified_at IS NULL) OR (classified_at < updated_at));

CREATE INDEX work_items_assignees ON public.work_items USING gin (assignees);

CREATE INDEX work_items_resources ON public.work_items USING gin (resources);

ALTER TABLE ONLY public.group_members
    ADD CONSTRAINT group_members_group_id_fkey FOREIGN KEY (group_id) REFERENCES public.groups(scim_id) ON DELETE CASCADE;

